for subj_data in [OOP, PRPR, DSA, IAU, MA]:
    by_diff = {"easy": [], "medium": [], "hard": []}
    for q in subj_data:
        by_diff[q["difficulty"]].append(q)
    picks = by_diff["easy"][:2] + by_diff["medium"][:2] + by_diff["hard"][:2]
    for p in picks:
        p["expected_answer_snippet"] = f"Odpoved by mala obsahovat: {', '.join(p['expected_keywords'][:3])}"
    golden_30.extend(picks)

for name, data in [("oop",OOP),("prpr",PRPR),("dsa",DSA),("iau",IAU),("ma",MA)]:
    (OUT / f"{name}.json").write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"{name}.json: {len(data)} questions")

(OUT / "golden_30.json").write_text(json.dumps(golden_30, ensure_ascii=False, indent=2), encoding="utf-8")
